// Email when the heartbeat goes down (then at most hourly while it stays down),
// and once when it recovers. Times and status only; no visit data.
const data = $getWorkflowStaticData('global');
const r = $input.first().json;
const status = typeof r.statusCode === 'number' ? r.statusCode : null;
const body = r.body && typeof r.body === 'object' ? r.body : {};
const healthy = status === 200 && body.ok === true;
const now = Date.now();
const at = $now.setZone('America/Winnipeg').toFormat('yyyy-MM-dd HH:mm');
if (healthy) {
  if (data.downSince) {
    const mins = Math.round((now - data.downSince) / 60000);
    data.downSince = null;
    data.lastEmail = null;
    return [{ json: {
      subject: '[TEST watchdog] [AlayaCare 1021] Alert checks running again',
      text: 'Alert checks are running again as of ' + at + ' (Winnipeg time). They were down for about ' + mins + ' minutes. Missed-shift alerts for that time may not have been sent; check AlayaCare for visits without a clock-in.'
    } }];
  }
  return [];
}
if (!data.downSince) data.downSince = now;
if (data.lastEmail && now - data.lastEmail < 3600000) return [];
data.lastEmail = now;
const why = status === null
  ? 'The dashboard did not answer (' + (r.error && r.error.message ? r.error.message : 'no response') + ').'
  : status === 503
    ? 'No alert check has succeeded for ' + body.minutes_since + ' minutes (last success: ' + (body.last_ok_at || 'none since the service started') + ').'
    : 'The heartbeat answered HTTP ' + status + '.';
return [{ json: {
  subject: '[TEST watchdog] [AlayaCare 1021] Missed-shift alerts are NOT running',
  text: 'Checked at ' + at + ' (Winnipeg time).\n' + why + '\n\nUntil this is fixed, no missed-shift alerts are being sent. Check that the n8n alerts workflow is active and see the dashboard container logs in Coolify. This email repeats hourly while the problem lasts.'
} }];
